S = "Hakeem Force Academy"
QS = [
 (S, "Which prophet is reported in a hadith to have worked as a carpenter?", ["Hazrat Zakariya (AS)", "Hazrat Dawud (AS)", "Hazrat Idris (AS)", "Hazrat Yahya (AS)"], 0,
  "Sahih Muslim reports that Hazrat Zakariya (AS) was a carpenter.", "Hazrat Dawud (AS) is known for making iron armour, and Hazrat Idris (AS) for tailoring.", [593, 1487]),
 (S, "For which book is Gulbadan Begum, daughter of Babur, famous as a writer?", ["Humayun-nama", "Baburnama", "Akbarnama", "Ain-i-Akbari"], 0,
  "Gulbadan Begum wrote the Humayun-nama, a history of the reign of her brother Humayun.", "She was one of the first Mughal women to write history.", [2696]),
 (S, "Who wrote the Urdu poetry book Bang-e-Dara?", ["Faiz Ahmad Faiz", "Allama Iqbal", "Altaf Hussain Hali", "Mirza Ghalib"], 1,
  "Bang-e-Dara is the first Urdu poetry collection of Allama Muhammad Iqbal.", "It was published in 1924.", [1255]),
 (S, "Who wrote the work The Loyal Muhammadans of India?", ["Sir Syed Ahmad Khan", "Allama Iqbal", "Maulana Muhammad Ali Jauhar", "Nawab Salimullah"], 0,
  "Sir Syed Ahmad Khan wrote it around 1860 to show that most Muslims were loyal to the British during the events of 1857.", "Sir Syed also wrote Asar-us-Sanadid and founded the Aligarh movement.", [4432]),
 (S, "What is the name of the cloth worn by pilgrims during Hajj?", ["Ihram", "Jubba", "Kiswa", "Imama"], 0,
  "Ihram is the simple unstitched white cloth that pilgrims wear after making the intention for Hajj or Umrah.", "A male pilgrim wears two pieces of cloth in the state of Ihram.", [504]),
 (S, "What was the name of the mother of Hazrat Yaqoob (AS)?", ["Hajra", "Sarah", "Rifqa (Rebecca)", "Zulaikha"], 2,
  "Hazrat Yaqoob (AS) was the son of Hazrat Ishaq (AS) and Rifqa (Rebecca).", "Hazrat Yaqoob (AS) is also known as Israel.", [4404]),
 (S, "What is the relation between Hazrat Zakariya (AS) and Hazrat Yahya (AS)?", ["Brothers", "Father and son", "Uncle and nephew", "Grandfather and grandson"], 1,
  "Hazrat Yahya (AS) was the son of Hazrat Zakariya (AS), born in his old age by Allah's will.", "Hazrat Yahya (AS) is mentioned in Surah Maryam.", [3122]),
 (S, "What was the relation of Hazrat Zaid bin Haritha (RA) with the Holy Prophet (SAW)?", ["Cousin", "Adopted son", "Uncle", "Brother-in-law"], 1,
  "Hazrat Zaid bin Haritha (RA) was a freed slave whom the Prophet (SAW) adopted as his son before Islam.", "He is the only Companion named in the Quran (Surah Al-Ahzab).", [3349]),
 (S, "In which year did Zakat become compulsory (enforced by law) in Pakistan?", ["1977", "1979", "1980", "1985"], 2,
  "The Zakat and Ushr Ordinance was promulgated in 1980 under General Zia-ul-Haq, and Zakat deduction from bank accounts started that year.", "Zakat is deducted from savings accounts on the first of Ramadan.", [550, 3506, 2866]),
 (S, "Which word is the closest in meaning (synonym) to zeal?", ["Laziness", "Enthusiasm", "Sorrow", "Anger"], 1,
  "Zeal means great energy and eagerness for a cause or an aim, which is enthusiasm.", "Its opposite (antonym) is apathy.", [63, 502, 948]),
 (S, "Is zero a natural number, according to the definition taught in Pakistani textbooks?", ["Yes, it is the first natural number", "No, it is a whole number", "No, it is a negative number", "Yes, it is a prime number"], 1,
  "Natural numbers are the counting numbers 1, 2, 3 and so on. Zero is added to them to form the whole numbers.", "Some modern books include zero among the natural numbers, so definitions differ.", [2239]),
 (S, "What is the result when a real number is divided by zero?", ["Zero", "One", "Infinity", "Undefined"], 3,
  "Division by zero has no meaning in mathematics, so the result is undefined.", "Zero divided by a non-zero number is zero.", [1009]),
 (S, "If A = 1, then what number matches M in the same pattern?", ["12", "14", "13", "11"], 2,
  "Letters are numbered by their place in the alphabet. A is 1st, and M is the 13th letter.", "N, the letter after M, is 14.", [1321]),
 (S, "What is the value of (3 + 2i)(3 - 2i)?", ["5", "9", "13", "5 + 12i"], 2,
  "(a + b)(a - b) = a squared - b squared. So 9 - 4i squared = 9 + 4 = 13, since i squared is -1.", "A complex number multiplied by its conjugate always gives a real number.", [2606]),
 (S, "What is 1 + 1?", ["2", "11", "1", "3"], 0,
  "Adding one and one gives two.", "In binary, 1 + 1 equals 10.", [2609]),
 (S, "What is 1.2 + 2/2?", ["2.1", "2.2", "1.6", "3.2"], 1,
  "Divide first: 2/2 = 1. Then 1.2 + 1 = 2.2.", "By BODMAS, division is done before addition.", [2610]),
 (S, "What is 1/(1 + 2)?", ["1/2", "3", "1/3", "2/3"], 2,
  "First solve the bracket: 1 + 2 = 3. So the value is 1/3.", "Brackets are solved first in BODMAS.", [2611]),
 (S, "What is 1/3 of 10% of 90?", ["9", "30", "27", "3"], 3,
  "10% of 90 = 9. One third of 9 = 3.", "10% of a number is the same as one tenth of it.", [894]),
 (S, "What is 2 + 4 x 4?", ["24", "18", "16", "32"], 1,
  "Multiply first: 4 x 4 = 16. Then 2 + 16 = 18.", "By BODMAS, multiplication is done before addition.", [2616]),
 (S, "What is 3 x 2?", ["5", "8", "6", "9"], 2,
  "3 x 2 = 6, and 2 x 3 is also 6 because multiplication is commutative.", "Changing the order of numbers does not change a product.", [2621]),
 (S, "What is 4 + 4 x 4?", ["20", "32", "16", "24"], 0,
  "Multiply first: 4 x 4 = 16. Then 4 + 16 = 20.", "If addition were done first the answer would wrongly be 32.", [2622]),
 (S, "What is 40% of 9?", ["4.5", "3.6", "36", "0.36"], 1,
  "40% of 9 = 40/100 x 9 = 360/100 = 3.6.", "10% of 9 is 0.9, so 40% is four times that.", [2623]),
]
